from book import Chapter
c=Chapter('23')
c.src('ORIGINAL',89,replacements=[('从一个抽象的数学概念“对偶体”出发','从存在、变化与可构造性的问题出发'),('极具野心','抱负很大')],note='用户指定底稿的收束段；将出发点调整为本稿展开的概念，底稿自身作者构成未独立核实')
c.src('R55321',0,start='我说的这些，思路跳跃性有点大',end='最快的速度达到涌现新不动点稳定结构的目的。',replacements=[('我说的这些，思路跳跃性有点大，想法听起来有些异想天开，天方夜谭，但第一性原理的直觉，让我很趋向于这个人类进化路径的可行性','这些想法跨越的范围很大，听起来甚至有些异想天开。但从基本问题出发的直觉，使我愿意认真探索这条人类文明演化路径的可能性'),('它也遵循不动点+最小化的涌现机制，而我设想的机制不过是一个涌现效率更高的文明机制而已','我希望用不动点、最小化与涌现的联系研究这个过程，并尝试构造一种能够更有效促进文明发展的机制'),('你之前提到的报复策略，如果换句话说，这些人类的博弈行为，其实就是通过不断博弈达成的纳什均衡，来构造人类社会结构的不动点稳定结构的一种最小化进程','从这个角度看，人类反复博弈、形成相对稳定的合作关系，也是值得研究的结构形成过程'),('而我设想的那种虚拟的以牙还牙策略，将会彻底消除经济和政治权力和决策权重的调整所带来的这些低效的损耗','而我设想通过信息反馈、动态权重和可修正的共同决策，减少这种调整过程中的破坏与浪费'),('用最低的能量，最快的速度达到涌现新不动点稳定结构的目的','以更低的消耗，形成更适合共同生活与创造的稳定结构')],note='作者文明演化主张；将尚无证明的必然性、彻底消除和最优性断言改为研究目标，改动待作者审阅')
c.add('''一个宏大的目标，要从哪里开始？如果必须等到所有人同意、所有资源齐备、所有理论问题都已解决，任何新的合作都无法发生。但如果只顾向前扩张，不把自己的组织方式放进实践，也可能在规模增长中重新形成原来想改变的关系。

因此，第一步应当足够小，小到一个人能够开始；它又必须带着整体方向，使后来加入的人知道，自己参与的究竟是什么。从取回自己的数据开始，建立可支配的知识与存储空间；从一个真实服务开始，学习怎样共同维护它；从一段原话、一项修改、一次失败的记录开始，让贡献与决策可以追溯；从写出一个故事、解释清楚一个问题开始，让更多人能够判断是否愿意参与。

这些事放在一起，才构成了我所说的种子。它既包含软件，也包含人怎样合作；既包含知识的保存，也包含新的知识怎样生成；既关心今天能解决什么问题，也为明天可能出现的能力保留生长的空间。''')
c.src('SEED-R14-0',1,start='至少从现在看，这个设想已经吸引到了一个人',end='将这个设想从一颗种子变成一个参天大树。',replacements=[('通过互联网和现实中的宣传，争取吸引更多的人参与','通过互联网和现实中的交流，争取吸引更多的人参与')])
c.add('''参与并不意味着先承认全部结论。一个人可以带着问题、不同意见和自己的经验加入。只要愿意把问题说清楚，把尝试留下来，把可以分享的知识交给别人继续使用，就已经在共同构造这个未来。

我希望最终形成的文明，不是让绝大多数人等待少数人的创造，也不是让某个超级智能代替所有人生活。每一个人都能够学习、判断、实践和创造；每一个人又都不必独自承担一切。人的不同，成为相互补充的来源；共同积累的能力，成为每个人继续发展的条件。

我们无法在今天写完未来的全部答案。但是，可以从今天开始改变产生答案的方式。''')
c.save({'reasoning':'统一框架的抱负→把效率与和平作为研究目标→足够小且方向明确的种子→参与者共同创造','examples':['个人数据与知识空间','真实服务的共同维护','不同意见的参与'],'objections':['是否等所有问题解决才能开始','参与是否要求先接受全部结论'],'voice':'底稿与作者原话承担核心收束；起步串联和最后段落为编辑补写','status':'初校；不宣称宏观理论已证明'})
